"use strict";function query(n){$.ajax({url:_global.root+"applicants/index",dataType:"html",method:"POST",data:{FullName:$("#FullName").val(),PositionId:$("#PositionId").val(),Status:$("#Status").val(),FromDate:$("#FromDate").val(),ToDate:$("#ToDate").val(),PageNumber:$("#PageNumber").val(),PageSize:$("#PageSize").val()},beforeSend:function(){n||$(".loading-process").fadeIn(300)},success:function(n){$("#applicants-detail").html(n);floatThead("table#data");showRowInfo();disableBtnPreNext()},error:function(){alert(_messages.errorTryAgain)},complete:function(){n||$(".loading-process").fadeOut(300)}})}function deleteApplicant(n,t){confirm("Are you sure you want to delete this applicant?",function(){$.post(_global.root+"applicants/Delete",{id:n,fileName:t},function(t){t.IsSuccessful?($("#row"+n).remove(),autoIndex()):alert(t.Message)})})}function eventExportExcel(){$("#exportExcel").on("click",function(n){n.preventDefault();window.location.href=_global.root+"Export/ApplicantsReport?fullName="+$("#FullName").val()+"&positionId="+$("#PositionId").val()+"&status="+$("#Status").val()+"&fromDate="+$("#FromDate").val()+"&toDate="+$("#ToDate").val()})}function pageSizeChanged(){query(!1)}function showRowInfo(){const n=document.getElementById("total-row").value,t=document.querySelector(".pagination"),i=document.getElementById("item-range-start"),r=document.getElementById("item-range-end"),u=document.getElementById("total-items");if(n!=0){const f=document.getElementById("PageNumber").value,e=document.getElementById("PageSize").value,o=(f-1)*e+1,s=f*e;i.textContent=o;r.textContent=Math.min(s,n);u.textContent=n;t.style.display=""}else t.style.display="none"}function disableBtnPreNext(){const i=parseInt(document.getElementById("total-row").value,10),r=parseInt(document.getElementById("PageSize").value,10),t=Math.ceil(i/r),n=document.getElementById("PageNumber").value,u=document.querySelector(".mdi-chevron-left"),f=document.querySelector(".mdi-chevron-double-left"),e=document.querySelector(".mdi-chevron-right"),o=document.querySelector(".mdi-chevron-double-right");u.classList.toggle("disabled",n==1);f.classList.toggle("disabled",n==1);e.classList.toggle("disabled",n==t);o.classList.toggle("disabled",n==t)}function clickBtnPrevNext(){function u(){const n=parseInt(t.value,10),r=parseInt(i.value,10);return Math.ceil(n/r)}function f(t){switch(t){case"btnDoublePrev":n.value=1;break;case"btnPrev":n.value=parseInt(n.value)-1;break;case"btnDoubleNext":n.value=r;break;case"btnNext":n.value=parseInt(n.value)+1}}const n=document.getElementById("PageNumber"),t=document.getElementById("total-row"),i=document.getElementById("PageSize"),r=u();["btnDoublePrev","btnPrev","btnDoubleNext","btnNext"].forEach(function(n){const t=document.getElementById(n);t.addEventListener("click",function(t){t.preventDefault();f(n);query(!1)})})}$(document).ready(function(){$("#FullName").keyup(function(n){n.keyCode===13&&query(!1)});$("#PageNumber").keyup(function(n){if(n.keyCode===13){const n=parseInt(document.getElementById("total-row").value,10),t=parseInt(document.getElementById("PageSize").value,10),i=Math.ceil(n/t),r=document.getElementById("PageNumber").value;i>=r&&query(!1)}});$("#submit").on("click",function(){query(!1)});query(!0);eventExportExcel();pageSizeChanged();clickBtnPrevNext()});